    parse_record('name=Ana; city = Lyon') == {"name": "Ana", "city": "Lyon"}
    parse_record('note="a;b"; urgent') == {"note": "a;b", "urgent": True}
    """
    fields = []
    current = []
    in_quotes = False
    i = 0
    n = len(line)

    while i < n:
        c = line[i]
        if in_quotes:
            if c == '\\' and i + 1 < n and line[i + 1] == '"':
                current.append('\\"')
                i += 2
                continue
            elif c == '"':
                in_quotes = False
            current.append(c)
        else:
            if c == '"':
                in_quotes = True
                current.append(c)
            elif c == ';':
                fields.append("".join(current))
                current = []
            else:
                current.append(c)
        i += 1
    fields.append("".join(current))

    result = {}
    for field in fields:
        field_stripped = field.strip()
        if not field_stripped:
            continue
        if '=' in field:
            key, val = field.split('=', 1)
            key = key.strip()
            val = val.strip()
            if len(val) >= 2 and val.startswith('"') and val.endswith('"'):
                val = val[1:-1].replace('\\"', '"')
            result[key] = val
        else:
            result[field_stripped] = True

    return result

