def shell_sort(my_list):
    gap = len(my_list) // 2
    while gap > 0:
        i = 0
        j = gap
        while j < len(my_list):
            if my_list[i] > my_list[j]:
                my_list[i], my_list[j] = my_list[j], my_list[i]
            i += 1
            j += 1
            k = i
            while k - gap > -1:
                if my_list[k - gap] > my_list[k]:
                    my_list[k - gap], my_list[k] = my_list[k], my_list[k - gap]
                k -= 1
        gap //= 2
    return my_list

